@@ -43,10 +43,36 @@ public final class ReservationService {
             throw new HotelException(
                     ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
         }
-        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
+
+        Price price = switch (request.ratePlan()) {
+            case CORPORATE -> {
+                if (request.companyCode() == null || !isValidCompanyCode(request.companyCode())) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "invalid or missing company code");
+                }
+                yield priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
+            }
+            case WEEKEND_PACKAGE -> {
+                if (!PriceCalculator.isWeekendPackageValid(request.checkIn(), request.checkOut())) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must be Friday to Sunday");
+                }
+                yield priceCalculator.calculateWeekendPackage(room, request.checkIn(), request.checkOut());
+            }
+            case LONG_STAY -> {
+                int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
+                if (nights < 7) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
+                }
+                yield priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), null);
+            }
+            case STANDARD, NON_REFUNDABLE -> priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), null);
+        };
         return store.add(request, price);
     }

+    private static boolean isValidCompanyCode(String code) {
+        return code.equals("TECNOSUL") || code.equals("AGROVALE") || code.equals("FARMAVIDA");
+    }
+
     public Reservation find(long reservationId) {
         return store.find(reservationId)
                 .orElseThrow(() -> new HotelException(
@@ -80,8 +106,9 @@ public final class ReservationService {
             throw notAllowed(reservation, "cancel");
         }
         BigDecimal refund = switch (reservation.ratePlan()) {
-            case STANDARD -> reservation.amountPaid();
+            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
             case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
+            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().divide(new java.math.BigDecimal("2"), 2, java.math.RoundingMode.HALF_EVEN));
         };
         reservation.cancel(refund);
         store.update(reservation);
