 82	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 83	    public synchronized Reservation confirm(long reservationId) {
 84	        Reservation reservation = find(reservationId);
 85	        if (reservation.status() != ReservationStatus.PENDING) {
 86	            throw notAllowed(reservation, "confirm");
 87	        }
 88	        reservation.confirmPayment();
 89	        store.update(reservation);
 90	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 91	        emailSender.send(
 92	                reservation.guest().email(),
 93	                "Reserva confirmada - " + HOTEL_NAME,
 94	                confirmationEmailBody(reservation, receipt));
 95	        return reservation;
 96	    }
