  7	import java.time.DayOfWeek;
  8	import java.time.LocalDate;
  9	import java.time.Month;
 10	
 11	/**
 12	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 13	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 14	 * (half-even) at every step.
 15	 */
 16	public final class PriceCalculator {
 17	
 18	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 19	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 20	    static final BigDecimal CORPORATE_TECNOSUL_DISCOUNT = new BigDecimal("0.12");
 21	    static final BigDecimal CORPORATE_AGROVALE_DISCOUNT = new BigDecimal("0.18");
 22	    static final BigDecimal CORPORATE_FARMAVIDA_DISCOUNT = new BigDecimal("0.25");
 23	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 24	
 25	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 26	        int nights = 0;
 27	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 28	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 29	            subtotal = subtotal.add(nightPrice(room, night));
 30	            nights++;
 31	        }
 32	        BigDecimal discount = switch (ratePlan) {
 33	            case STANDARD -> cents(BigDecimal.ZERO);
 34	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 35	            case CORPORATE -> cents(subtotal.multiply(getCorporateDiscount(companyCode)));
 36	            case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
 37	            case WEEKEND_PACKAGE -> cents(BigDecimal.ZERO);
 38	        };
 39	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 40	    }
 41	
 42	    public Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
 43	        BigDecimal packagePrice = switch (room.type()) {
 44	            case STANDARD -> new BigDecimal("520.00");
 45	            case DELUXE -> new BigDecimal("820.00");
 46	            case SUITE -> new BigDecimal("1200.00");
 47	        };
 48	        return new Price(2, packagePrice, cents(BigDecimal.ZERO), packagePrice);
 49	    }
 50	
 51	    private static BigDecimal getCorporateDiscount(String companyCode) {
 52	        return switch (companyCode) {
 53	            case "TECNOSUL" -> CORPORATE_TECNOSUL_DISCOUNT;
 54	            case "AGROVALE" -> CORPORATE_AGROVALE_DISCOUNT;
 55	            case "FARMAVIDA" -> CORPORATE_FARMAVIDA_DISCOUNT;
 56	            default -> throw new IllegalArgumentException("Invalid company code: " + companyCode);
 57	        };
 58	    }
 59	
 60	    BigDecimal nightPrice(Room room, LocalDate night) {
 61	        BigDecimal nightlyRate = room.nightlyRate();
 62	        if (isHighSeason(night)) {
 63	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 64	        }
 65	        return cents(nightlyRate);
 66	    }
 67	
 68	    /** High season: from December 15 to the end of February, and the whole of July. */
 69	    static boolean isHighSeason(LocalDate date) {
 70	        Month month = date.getMonth();
 71	        return month == Month.JANUARY
 72	                || month == Month.FEBRUARY
 73	                || month == Month.JULY
 74	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
 75	    }
 76	
 77	    static BigDecimal cents(BigDecimal value) {
 78	        return value.setScale(2, RoundingMode.HALF_EVEN);
 79	    }
 80	
 81	    static boolean isWeekendPackageValid(LocalDate checkIn, LocalDate checkOut) {
 82	        if (!checkOut.minusDays(1).equals(checkIn.plusDays(1))) {
 83	            return false;
 84	        }
 85	        return checkIn.getDayOfWeek() == DayOfWeek.FRIDAY && checkOut.getDayOfWeek() == DayOfWeek.SUNDAY;
 86	    }
 87	}
